namespace FrameGrabber;
public partial class MainWindow : Window
{
    private readonly MediaService media = new(); private VideoInfo? video; private string folder = Environment.GetFolderPath(Environment.SpecialFolder.MyPictures); private bool suppress; private bool suppressChapterSelection; private bool previewedOnDown; private bool? stacked; private int previewGeneration; private readonly ObservableCollection<QueueItem> queue = new(); private ImageSource? lastPreview;
    public MainWindow() { InitializeComponent(); WindowFrame.Attach(this, Root, MinimizeButton, MaximizeButton, CloseButton, 40); WireCommands(); QueueList.ItemsSource = queue; queue.CollectionChanged += (_, _) => UpdateQueueChrome(); UpdateQueueChrome(); Timeline.PreviewMouseLeftButtonDown += Timeline_Click; TimelineMarks.SizeChanged += (_, _) => DrawTimelineMarks(); SetChapterControlsVisibility(false); if (!string.IsNullOrWhiteSpace(App.Settings.ExportFolder)) folder = App.Settings.ExportFolder; FolderText.Text = folder; Closing += (_, e) => { if (pendingUpdateSetup is null && !ConfirmDiscard()) e.Cancel = true; }; Loaded += (_, _) => { StartUpdateChecks(); if (Environment.GetCommandLineArgs() is [_, var file, ..] && File.Exists(file)) LoadVideo(file); }; }
    private async void Window_Loaded(object s, RoutedEventArgs e) { try { if (MediaTools.IsAvailable("ffmpeg") && MediaTools.IsAvailable("ffprobe")) return; } catch (Exception ex) { StatusText.Text = "Could not prepare bundled FFmpeg tools."; System.Windows.MessageBox.Show(ex.Message, "FrameGrabber", MessageBoxButton.OK, MessageBoxImage.Error); return; } if (MediaTools.AreBundled) { StatusText.Text = "Bundled FFmpeg tools are unavailable."; return; } var answer = System.Windows.MessageBox.Show("FrameGrabber needs FFmpeg and FFprobe to read videos and render frames. Would you like to install them automatically with Windows Package Manager?", "FFmpeg required", MessageBoxButton.YesNo, MessageBoxImage.Information); if (answer != MessageBoxResult.Yes) { StatusText.Text = "FFmpeg and FFprobe are required to use FrameGrabber."; return; } if (!MediaTools.IsAvailable("winget")) { System.Windows.MessageBox.Show("Windows Package Manager (winget) is not available. Install FFmpeg manually, then restart FrameGrabber.", "FFmpeg required", MessageBoxButton.OK, MessageBoxImage.Warning); return; } StatusText.Text = "Installing FFmpeg…"; var exitCode = await Task.Run(InstallFfmpeg); if (exitCode == 0 && MediaTools.IsAvailable("ffmpeg") && MediaTools.IsAvailable("ffprobe")) StatusText.Text = "FFmpeg installed — ready"; else { StatusText.Text = "FFmpeg installation needs a restart."; System.Windows.MessageBox.Show("FFmpeg was installed or updated, but Windows has not refreshed this app's PATH yet. Please restart FrameGrabber.", "Restart required", MessageBoxButton.OK, MessageBoxImage.Information); } }
    private static int InstallFfmpeg() { try { using var p = Process.Start(new ProcessStartInfo("winget", "install --id Gyan.FFmpeg.Essentials -e --accept-source-agreements --accept-package-agreements") { UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true, CreateNoWindow = true }); p?.WaitForExit(); return p?.ExitCode ?? -1; } catch { return -1; } }
    private void Window_DragOver(object s, System.Windows.DragEventArgs e) { var ok = e.Data.GetDataPresent(System.Windows.DataFormats.FileDrop); e.Effects = ok ? System.Windows.DragDropEffects.Copy : System.Windows.DragDropEffects.None; e.Handled = true; DropOverlay.Visibility = ok ? Visibility.Visible : Visibility.Collapsed; }
    private void Window_DragLeave(object s, System.Windows.DragEventArgs e) { var pos = e.GetPosition(this); if (pos.X <= 0 || pos.Y <= 0 || pos.X >= ActualWidth || pos.Y >= ActualHeight) DropOverlay.Visibility = Visibility.Collapsed; }
    private void Window_Drop(object s, System.Windows.DragEventArgs e) { DropOverlay.Visibility = Visibility.Collapsed; if (e.Data.GetData(System.Windows.DataFormats.FileDrop) is string[] files && files.Length > 0) LoadVideo(files[0]); }
    private void Window_SizeChanged(object s, SizeChangedEventArgs e) => ApplyLayout(e.NewSize.Width);
    private void ApplyLayout(double width) { if (width < 1 || SidePanel is null) return; var narrow = width < 980; if (stacked == narrow) return; stacked = narrow; if (narrow) { SideColumn.Width = new GridLength(0); StackRow.Height = GridLength.Auto; System.Windows.Controls.Grid.SetColumn(SidePanel, 0); System.Windows.Controls.Grid.SetRow(SidePanel, 1); SidePanel.Margin = new Thickness(0, 14, 0, 0); } else { SideColumn.Width = new GridLength(356); StackRow.Height = new GridLength(0); System.Windows.Controls.Grid.SetColumn(SidePanel, 1); System.Windows.Controls.Grid.SetRow(SidePanel, 0); SidePanel.Margin = new Thickness(14, 0, 0, 0); } }
    private async void Window_PreviewKeyDown(object s, System.Windows.Input.KeyEventArgs e) { if (video is null || e.OriginalSource is System.Windows.Controls.TextBox or System.Windows.Controls.ComboBox or System.Windows.Controls.ComboBoxItem or System.Windows.Controls.MenuItem) return; var ctrl = Keyboard.Modifiers.HasFlag(ModifierKeys.Control); var shift = Keyboard.Modifiers.HasFlag(ModifierKeys.Shift); if (e.Key is Key.Left or Key.Right) { var sign = e.Key == Key.Right ? 1 : -1; e.Handled = true; if (ctrl) await GoTo(TimeSpan.FromSeconds(Timeline.Value + sign * 5)); else if (shift) await GoTo(TimeSpan.FromSeconds(Timeline.Value + sign)); else await StepFrame(sign); } else if (e.Key is Key.PageUp or Key.PageDown && !ctrl && e.OriginalSource is not ListBoxItem) { e.Handled = true; if (e.Key == Key.PageUp) ChapterBack_Click(this, new RoutedEventArgs()); else ChapterForward_Click(this, new RoutedEventArgs()); } }
    private void UpdateQueueChrome() { var count = queue.Count; QueueCountText.Text = count == 1 ? "1 frame" : $"{count} frames"; QueueEmpty.Visibility = count == 0 ? Visibility.Visible : Visibility.Collapsed; ExportAllButton.Content = count > 1 ? $"Export all {count}" : "Export all"; DrawTimelineMarks(); CommandManager.InvalidateRequerySuggested(); }
    private void Browse_Click(object s, RoutedEventArgs e) { using var d = new Forms.OpenFileDialog { Filter = "Video files|*.mkv;*.mp4;*.mov;*.webm;*.avi;*.m4v;*.ts|All files|*.*" }; if (d.ShowDialog() == Forms.DialogResult.OK) LoadVideo(d.FileName); }
    private async void LoadVideo(string path) => await OpenVideo(path);
    private async Task OpenVideo(string path) { var generation = workspaceGeneration; try { StatusText.Text = "Reading video metadata…"; var probed = await Task.Run(() => media.Probe(path)); if (generation != workspaceGeneration) return; video = probed; FileNameText.Text = video.FileName; FilePathText.Text = path; VideoChips.Visibility = Visibility.Visible; ResolutionText.Text = $"{video.Width} × {video.Height}"; CodecText.Text = $"{video.Codec} {video.BitDepth}-bit"; DepthText.Text = string.IsNullOrWhiteSpace(video.PixelFormat) ? "pixel format unknown" : video.PixelFormat; FpsText.Text = $"{FormatRate(video.FrameRate)} fps"; ShowTitle(); DurationText.Text = FormatFrame(video.Duration); Timeline.Maximum = Math.Max(video.Duration.TotalSeconds, 0.001); Timeline.Value = 0; ChapterPicker.ItemsSource = video.Chapters; SetChapterControlsVisibility(video.Chapters.Count > 0); SyncChapterPicker(Timeline.Value); TransportPanel.IsEnabled = true; PreviewMeta.Visibility = Visibility.Visible; UpdateQueueChrome(); CommandManager.InvalidateRequerySuggested(); HdrBadge.Visibility = video.IsHdr ? Visibility.Visible : Visibility.Collapsed; HdrText.Text = $"{(video.IsDolbyVision ? "Dolby Vision" : "HDR")}. Previews and PNGs are tone-mapped to SDR BT.709."; PreviewHdrTag.Visibility = HdrBadge.Visibility; PreviewHdrText.Text = video.IsDolbyVision ? "DOLBY VISION → SDR" : "HDR → SDR"; ColorText.Text = string.Join("  ·  ", new[] { string.IsNullOrWhiteSpace(video.ColorSpace) ? "Color space unknown" : video.ColorSpace, string.IsNullOrWhiteSpace(video.Transfer) ? "transfer unknown" : video.Transfer, video.Primaries }.Where(part => !string.IsNullOrWhiteSpace(part))); StatusText.Text = video.IsHdr ? "HDR preview active — exports are tone-mapped to SDR" : "Video loaded — choose a moment to export"; await UpdatePreview(); } catch (Exception ex) { StatusText.Text = "Could not read video."; System.Windows.MessageBox.Show(ex.Message, "FrameGrabber", MessageBoxButton.OK, MessageBoxImage.Warning); } }
    private void Timeline_ValueChanged(object s, RoutedPropertyChangedEventArgs<double> e) { if (video is null || suppress || !IsLoaded) return; CurrentTimeText.Text = FormatFrame(TimeSpan.FromSeconds(e.NewValue)); TimeInput.Text = CurrentTimeText.Text; SyncChapterPicker(e.NewValue); }
    private async void Timeline_Click(object? sender, MouseButtonEventArgs e) { if (video is null || IsInsideThumb(e.OriginalSource as DependencyObject)) return; var point = e.GetPosition(Timeline); var ratio = Math.Clamp(point.X / Math.Max(Timeline.ActualWidth, 1), 0, 1); e.Handled = true; previewedOnDown = true; await GoTo(TimeSpan.FromSeconds(ratio * video.Duration.TotalSeconds)); }
    private async void Timeline_PreviewMouseUp(object s, MouseButtonEventArgs e) { if (previewedOnDown) { previewedOnDown = false; return; } await UpdatePreview(); }
    private static bool IsInsideThumb(DependencyObject? source) { while (source is not null) { if (source is Thumb) return true; source = VisualTreeHelper.GetParent(source); } return false; }
    private async void TimeInput_KeyDown(object s, System.Windows.Input.KeyEventArgs e) { if (e.Key != Key.Enter) return; e.Handled = true; await SeekFromInput(); }
    private async void Go_Click(object s, RoutedEventArgs e) => await SeekFromInput();
    private async Task SeekFromInput() { if (video is null) { StatusText.Text = "Open a video first."; return; } if (!TryResolveFrame(TimeInput.Text, out var frame)) { StatusText.Text = "Use HH:MM:SS.frames, or a number of seconds."; return; } await GoToFrame(frame); }
    private Task UpdatePreview() => RenderPreview(FrameTime(Timeline.Value));
    private async Task RenderPreview(TimeSpan time) { var currentVideo = video; if (currentVideo is null) return; var generation = ++previewGeneration; try { StatusText.Text = "Rendering preview…"; var tmp = Path.Combine(Path.GetTempPath(), $"framegrabber-preview-{Guid.NewGuid():N}.png"); await Task.Run(() => media.Extract(currentVideo.FilePath, time, tmp, 900, currentVideo.IsHdr)); if (generation != previewGeneration) return; if (!File.Exists(tmp) || new FileInfo(tmp).Length == 0) throw new InvalidOperationException("FFmpeg did not create a preview image."); var image = new BitmapImage(); image.BeginInit(); image.CacheOption = BitmapCacheOption.OnLoad; var bytes = await File.ReadAllBytesAsync(tmp); try { File.Delete(tmp); } catch { } image.StreamSource = new MemoryStream(bytes); image.EndInit(); image.Freeze(); if (generation != previewGeneration) return; PreviewImage.Source = lastPreview = image; PreviewImage.Visibility = Visibility.Visible; PreviewTitle.Text = FormatFrame(time); TintBackdrop(bytes); DropHint.Visibility = Visibility.Collapsed; DropOutline.Visibility = Visibility.Collapsed; StatusText.Text = currentVideo.IsHdr ? "Preview tone-mapped to SDR" : "Preview ready"; } catch (Exception ex) { if (generation != previewGeneration) return; PreviewImage.Visibility = Visibility.Collapsed; DropHint.Visibility = Visibility.Visible; DropOutline.Visibility = Visibility.Visible; StatusText.Text = $"Preview unavailable: {ex.Message}"; } }
    private async void Export_Click(object s, RoutedEventArgs e) { if (video is null) return; try { Directory.CreateDirectory(folder); var frame = CurrentFrame(); var t = TimeOfFrame(frame); var name = $"{Path.GetFileNameWithoutExtension(video.FileName)}-{FormatFrameIndex(frame).Replace(':', '-')}.png"; var output = Path.Combine(folder, name); await Task.Run(() => media.Extract(video.FilePath, t, output, null, video.IsHdr)); StatusText.Text = $"Exported {name}"; } catch (Exception ex) { System.Windows.MessageBox.Show(ex.Message, "Export failed", MessageBoxButton.OK, MessageBoxImage.Error); } }
    private Task GoTo(TimeSpan time) => video is null ? Task.CompletedTask : GoToFrame(FrameIndex(time.TotalSeconds));
    private async Task GoToFrame(int frame) { if (video is null) return; frame = ClampFrame(frame); var exact = TimeOfFrame(frame); suppress = true; Timeline.Value = Math.Clamp(exact.TotalSeconds, 0, Math.Max(video.Duration.TotalSeconds, 0)); suppress = false; CurrentTimeText.Text = FormatFrameIndex(frame); TimeInput.Text = CurrentTimeText.Text; SyncChapterPicker(exact.TotalSeconds); await RenderPreview(exact); }
    private async void FrameBack_Click(object s, RoutedEventArgs e) => await StepFrame(-1);
    private async void FrameForward_Click(object s, RoutedEventArgs e) => await StepFrame(1);
    private async Task StepFrame(int delta) { if (video is null) return; await GoTo(TimeSpan.FromSeconds(Math.Max(0, FrameIndex(Timeline.Value) + delta) / FrameRate)); }
    private async void Rewind_Click(object s, RoutedEventArgs e) => await GoTo(TimeSpan.FromSeconds(Timeline.Value - 5));
    private async void Rewind1_Click(object s, RoutedEventArgs e) => await GoTo(TimeSpan.FromSeconds(Timeline.Value - 1));
    private async void FastForward1_Click(object s, RoutedEventArgs e) => await GoTo(TimeSpan.FromSeconds(Timeline.Value + 1));
    private async void FastForward_Click(object s, RoutedEventArgs e) => await GoTo(TimeSpan.FromSeconds(Timeline.Value + 5));
    private async void ChapterBack_Click(object s, RoutedEventArgs e) { if (video is null || video.Chapters.Count == 0) return; var i = video.Chapters.Select((c, n) => (c, n)).LastOrDefault(x => x.c.Start.TotalSeconds < Timeline.Value - 0.5).n; await GoTo(video.Chapters[Math.Clamp(i, 0, video.Chapters.Count - 1)].Start); }
    private async void ChapterForward_Click(object s, RoutedEventArgs e) { if (video is null || video.Chapters.Count == 0) return; var c = video.Chapters.FirstOrDefault(x => x.Start.TotalSeconds > Timeline.Value + 0.5); await GoTo(c?.Start ?? video.Chapters[^1].Start); }
    private async void ChapterPicker_SelectionChanged(object s, System.Windows.Controls.SelectionChangedEventArgs e) { if (suppressChapterSelection || ChapterPicker.SelectedItem is not ChapterInfo c || !IsLoaded) return; await GoTo(c.Start); }
    private void SyncChapterPicker(double seconds) { ChapterNameText.Text = ChapterAt(TimeSpan.FromSeconds(seconds)); if (video is null || video.Chapters.Count == 0) return; var index = video.Chapters.Select((chapter, i) => (chapter, i)).Where(x => x.chapter.Start.TotalSeconds <= seconds + 0.001).Select(x => x.i).DefaultIfEmpty(0).Last(); if (ChapterPicker.SelectedIndex == index) return; suppressChapterSelection = true; ChapterPicker.SelectedIndex = index; suppressChapterSelection = false; }
    private void SetChapterControlsVisibility(bool visible) => ChapterBar.Visibility = visible ? Visibility.Visible : Visibility.Collapsed;
    private void AddQueue_Click(object s, RoutedEventArgs e) { if (video is null) return; var frame = CurrentFrame(); var timecode = FormatFrameIndex(frame); if (queue.FirstOrDefault(q => QueueOrder(q) == frame) is { } existing) { QueueList.SelectedItem = existing; QueueList.ScrollIntoView(existing); StatusText.Text = $"{timecode} is already queued"; return; } RecordQueue("add frame"); var item = new QueueItem(timecode) { Thumbnail = PreviewImage.Visibility == Visibility.Visible ? lastPreview : null, Chapter = ChapterAt(TimeOfFrame(frame)) }; queue.Insert(queue.TakeWhile(q => QueueOrder(q) < frame).Count(), item); QueueList.SelectedItem = item; QueueList.ScrollIntoView(item); StatusText.Text = $"Queued {timecode}"; }
    private async void QueuePreview_Click(object s, RoutedEventArgs e) { if (((FrameworkElement)s).Tag is QueueItem q) await ShowQueued(q); }
    private async Task ShowQueued(QueueItem q) { if (video is null) return; if (!TryResolveFrame(q.Timecode, out var frame)) { StatusText.Text = "Use HH:MM:SS.frames, or a number of seconds."; return; } QueueList.SelectedItem = q; DrawTimelineMarks(); await GoToFrame(frame); if (PreviewTitle.Text == FormatFrameIndex(frame) && PreviewImage.Visibility == Visibility.Visible) q.Thumbnail = lastPreview; q.Chapter = ChapterAt(TimeOfFrame(frame)); }
    private void QueueRemove_Click(object s, RoutedEventArgs e) { if (((FrameworkElement)s).Tag is QueueItem q) RemoveQueued(q); }
    private void ClearQueue_Click(object s, RoutedEventArgs e) { if (queue.Count == 0) return; RecordQueue("clear the queue"); queue.Clear(); StatusText.Text = "Cleared the queue. Undo (Ctrl+Z) brings it back."; }
    private async void ImportQueue_Click(object s, RoutedEventArgs e) { if (!ConfirmDiscard()) return; using var d = new Forms.OpenFileDialog { Filter = "FrameGrabber queue|*.json" }; if (d.ShowDialog() != Forms.DialogResult.OK) return; try { using var doc = JsonDocument.Parse(File.ReadAllText(d.FileName)); var root = doc.RootElement; var source = root.TryGetProperty("Video", out var v) ? v.GetString() : null; if (!string.IsNullOrWhiteSpace(source) && File.Exists(source) && (video is null || !string.Equals(video.FilePath, source, StringComparison.OrdinalIgnoreCase))) { await OpenVideo(source); } RecordQueue("open queue"); queue.Clear(); if (root.TryGetProperty("Timecodes", out var times)) foreach (var t in times.EnumerateArray()) if (t.GetString() is string tc) queue.Add(new QueueItem(tc)); SortQueue(); queuePath = d.FileName; MarkQueueSaved(); StatusText.Text = $"Opened {Path.GetFileName(d.FileName)}"; await RefreshThumbnails(); } catch (Exception ex) { System.Windows.MessageBox.Show(ex.Message, "Queue import failed", MessageBoxButton.OK, MessageBoxImage.Warning); } }
    private async void ExportAll_Click(object s, RoutedEventArgs e) { if (video is null || queue.Count == 0) return; try { Directory.CreateDirectory(folder); var frames = new List<int>(); foreach (var item in queue) if (TryResolveFrame(item.Timecode, out var frame)) frames.Add(frame); foreach (var (frame, n) in frames.Select((f, i) => (f, i + 1))) { StatusText.Text = $"Exporting {n} of {frames.Count}…"; var t = TimeOfFrame(frame); var name = $"{Path.GetFileNameWithoutExtension(video.FileName)}-{FormatFrameIndex(frame).Replace(':', '-')}.png"; await Task.Run(() => media.Extract(video.FilePath, t, Path.Combine(folder, name), null, video.IsHdr)); } StatusText.Text = $"Exported {frames.Count} queued frame(s)"; } catch (Exception ex) { System.Windows.MessageBox.Show(ex.Message, "Batch export failed", MessageBoxButton.OK, MessageBoxImage.Error); } }
    private void Link_RequestNavigate(object sender, RequestNavigateEventArgs e) { Process.Start(new ProcessStartInfo(e.Uri.AbsoluteUri) { UseShellExecute = true }); e.Handled = true; }
    private double FrameRate => Math.Max(video?.FrameRate ?? 24, 1);
    private int NominalFps => Math.Max((int)Math.Round(FrameRate), 1);
    private int FrameIndex(double seconds) => Math.Max(0, (int)Math.Round(seconds * FrameRate, MidpointRounding.AwayFromZero));
    private int ClampFrame(int frame) { if (frame < 0) return 0; if (video is null) return frame; var last = FrameIndex(video.Duration.TotalSeconds); return frame > last ? last : frame; }
    private TimeSpan TimeOfFrame(int frame) => TimeSpan.FromSeconds(Math.Max(0, frame) / FrameRate);
    private int CurrentFrame() => TryResolveFrame(CurrentTimeText.Text, out var shown) ? shown : ClampFrame(FrameIndex(Timeline.Value));
    private TimeSpan FrameTime(double seconds) => TimeOfFrame(ClampFrame(FrameIndex(seconds)));
    private string FormatFrameIndex(int frame) { if (frame < 0) frame = 0; var whole = NominalFps; var seconds = frame / whole; var frames = frame % whole; return $"{seconds / 3600:00}:{seconds / 60 % 60:00}:{seconds % 60:00}.{frames:00}"; }
    private string FormatFrame(TimeSpan t) => FormatFrameIndex(FrameIndex(t.TotalSeconds));
    private bool TryParseFrame(string? value, out int frame)
    {
        frame = 0;
        if (string.IsNullOrWhiteSpace(value)) return false;
        var trimmed = value.Trim();
        var p = trimmed.Split(':');
        if (p.Length == 3 && int.TryParse(p[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out var h) && int.TryParse(p[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out var m))
        {
            var sf = p[2].Split('.');
            if (sf.Length == 2 && int.TryParse(sf[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out var sec) && int.TryParse(sf[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out var fr) && h >= 0 && m >= 0 && sec >= 0 && fr >= 0)
            {
                var index = ((long)h * 3600 + m * 60 + sec) * NominalFps + fr;
                frame = index > int.MaxValue ? int.MaxValue : (int)index;
                return true;
            }
        }
        if (double.TryParse(trimmed, NumberStyles.Float, CultureInfo.InvariantCulture, out var seconds)) { frame = FrameIndex(seconds); return true; }
        if (TimeSpan.TryParse(trimmed, CultureInfo.InvariantCulture, out var span)) { frame = FrameIndex(span.TotalSeconds); return true; }
        return false;
    }
    private bool TryResolveFrame(string? value, out int frame) { if (!TryParseFrame(value, out frame)) return false; frame = ClampFrame(frame); return true; }
}

